public class Main {
  static interface F {
    int apply(int x) throws Exception;
  }
  public static int run(F f) {
    try {
      return f.apply(3);
    }
    catch (Exception e) {
      return 7;
    }
  }
  public static void main(String[] args) {
    F f = (x) -> {
      if (x > 2) {
        throw new Exception();
      }
      return x * 2;
    };
    System.out.print(run(f) + run((int n) -> n + 9));
  }
}

public class Main{
  public static class Parent {
    public int x(int i) {
      return i + 2;
    }
    public static String id() {
      return "P";
    }
  }
  public static class Child extends Parent {
    public int x(int i) {
      return i + 3;
    }
    public String x(String s) {
      return s + "R";
    }
    public static String id() {
      return "C";
    }
  }
  public static void main(String[] args) {
    Parent ref = new Child();
    System.out.println(ref.x(2) + ref.id());
  }
}

#include <stdio.h>
#define SIZE 3
typedef struct {
  int a[SIZE];
  int front;
  int rear;
}
Queue;
void enq(Queue* q, int val){
  q->a[q->rear] = val;
  q->rear = (q->rear + 1) % SIZE;
}
int deq(Queue* q) {
  int val = q->a[q->front];
  q->front = (q->front + 1) % SIZE;
  return val;
}
int main() {
  Queue q = {{0}, 0, 0};
  enq(&q,1);
  enq(&q,2);
  deq(&q);
  enq(&q, 3);
  int first = deq(&q);
  int second = deq(&q);
  printf("%d 그리고 %d", first, second);
  return 0;
}

